# owner: platform
import unittest

from hourglass.errors import ProjectError
from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_rows


def shift(worker, day, start, end):
    return Shift(worker, day, Span(start * 60, end * 60))


class TimesheetRowsTests(unittest.TestCase):
    def test_one_line_per_worker(self):
        rows = timesheet_rows([
            shift("Ana", "mon", 9, 17),
            shift("Ana", "tue", 9, 13),
            shift("Bo", "mon", 9, 12)
        ])
        self.assertEqual(rows, [
            "Ana: 2 shifts, 12.0 hours",
            "Bo: 1 shift, 3.0 hours"
        ])

    def test_busiest_first(self):
        rows = timesheet_rows([
            shift("Bo", "mon", 9, 11),
            shift("Ana", "mon", 9, 17)
        ])
        self.assertTrue(rows[0].startswith("Ana"))

    def test_one_decimal_place(self):
        span = Span(9 * 60, 9 * 60 + 50)
        rows = timesheet_rows([Shift("Ana", "mon", span)])
        self.assertEqual(rows, ["Ana: 1 shift, 0.8 hours"])

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([shift("  ", "mon", 9, 10)])


if __name__ == "__main__":
    unittest.main()
